import sys,json,_codecs
r=[]
for data,policy,final in json.load(sys.stdin):
 try:
  text,n=_codecs.utf_7_decode(bytes(data),policy,final); r.append(['ok',list(map(ord,text)),n])
 except UnicodeDecodeError as e: r.append(['error',e.encoding,list(e.object),e.start,e.end,e.reason])
print(json.dumps(r))
